import json
from human_eval.data import read_problems
from human_eval.evaluation import evaluate_functional_correctness

# Path to the sample file containing model-generated code completions
# This file should be in JSONL format (JSON Lines) where each line contains:
# - task_id: The HumanEval problem identifier
# - completion: The code generated by the model
sample_file = "test/human_eval/models/Qwen3-14B_samples_pass@1.jsonl"

# k = [1] specifies that we only compute pass@1 metric
# pass@1 measures the probability that a single sample from the model passes the unit tests
# Other common values: k=[10] for pass@10, k=[100] for pass@100
results = evaluate_functional_correctness(
    sample_file,      # Path to the generated samples file
    k=[1],            # List of k values for pass@k calculation
    n_workers=8,      # Number of parallel workers for test execution
    timeout=3.0       # Timeout in seconds for each test execution
)

# Print evaluation results with decorative headers
print("\n====================")
print("Evaluation Results")
print("====================")

# Display each metric and its corresponding value
for key, value in results.items():
    print(f"{key}: {value}")